-- The ticket archive of Atlas Support: 50,000 older tickets for Chapter 7 (vector indexes).
-- Run as ATLAS after install.sql:  sql atlas@localhost:1521/FREEPDB1 @archive.sql
set define off feedback off
drop table if exists ticket_archive purge;

create table ticket_archive (
  archive_id   number         constraint ticket_archive_pk primary key,
  product_id   number         not null constraint ticket_archive_product_fk references products,
  category     varchar2(20)   not null,
  subject      varchar2(200)  not null,
  description  varchar2(1000) not null,
  created_on   date           not null
);
comment on table ticket_archive is 'Tickets of earlier years, kept for search: subject, text, product, and date';

insert all
  into ticket_archive values (1, 2, 'Billing', 'Invoice paid two times', 'Hi team, There is a double payment for our Professional plan this month. How do we get the money back? Our IT team already checked the network. Restarting did not help. We are on Atlas Billing 5.2.', date '2024-01-27')
