  into ticket_archive values (1450, 3, 'Bug', 'Offline changes lost', 'Good morning, I updated ten customer visits while I had no signal, and after reconnecting all my changes were gone. Thanks.', date '2023-02-27')
  into ticket_archive values (1451, 1, 'Bug', 'Pipeline view does not load', 'Good morning, The deals board is empty for everyone on the team. Yesterday it showed 120 open deals. We are on Atlas CRM 8.3. Please advise.', date '2021-10-17')
