  into ticket_archive values (1891, 2, 'Billing', 'Upgrade subscription mid-cycle', 'Hi, We want to move to the Enterprise plan this week. Will we pay the full price for this month? This is blocking our work. We are on Atlas Billing 5.0. Regards.', date '2022-03-29')
  into ticket_archive values (1892, 4, 'Account', 'Login keeps saying invalid credentials', 'Hello, Our sales manager is unable to access her account. The error is "invalid credentials" even with the new password from the reset link. This is blocking our work. We are on Atlas Analytics 6.1. Please advise.', date '2021-10-26')
  into ticket_archive values (1893, 3, 'Account', 'Change user role to admin', 'Good morning, How do I invite three new sales reps to our account? Thanks.', date '2022-12-12')
