  into ticket_archive values (2574, 6, 'Account', 'Change user role to admin', 'Hi, A new hire cannot see the billing section. How do I change her role? It only happens some of the time. It happens on every computer we tried. Thank you for your help.', date '2025-11-09')
  into ticket_archive values (2575, 4, 'Question', 'Export data to Excel', 'Hello, I need the raw data of the churn report as a CSV file. It worked fine last week.', date '2022-02-01')
