  into ticket_archive values (4835, 5, 'Bug', 'Webhooks not firing', 'Good morning, Our system no longer receives the deal.updated webhook. Nothing changed on our side. It worked fine last week. We need this fixed before the end of the month. Please advise.', date '2022-08-16')
  into ticket_archive values (4836, 1, 'Bug', 'Same customer appears twice', 'After uploading our spreadsheet the contact list is full of duplicates. How do we merge them? Restarting did not help. It only happens some of the time. It worked fine last week. We are on Atlas CRM 8.3. Please advise.', date '2024-07-25')
  into ticket_archive values (4837, 4, 'Account', 'Password reset e-mail not received', 'Hi team, Where is the reset link? I requested it an hour ago and still nothing in my inbox. Thank you for your help.', date '2024-06-25')
