  into ticket_archive values (5173, 4, 'Bug', 'Scheduled report not sent', 'Hello, Subscribers no longer receive the daily KPI report. Our IT team already checked the network. It worked fine last week. We are on Atlas Analytics 6.-1. Regards.', date '2025-10-08')
  into ticket_archive values (5174, 5, 'Question', 'Connect Atlas to Outlook calendar', 'Meetings booked in Atlas should show up in our calendar app. We are a small team, so this hurts. We are on Atlas Connect 4.-2.', date '2025-06-12')
  into ticket_archive values (5175, 5, 'Question', 'Calendar integration setup', 'Hi, Meetings booked in Atlas should show up in our calendar app. Thanks.', date '2021-09-21')
