  into ticket_archive values (6831, 2, 'Billing', 'Change plan from Professional to Enterprise', 'Good morning, We would like to downgrade to Basic when the contract renews next month. We need this fixed before the end of the month. This started after the last update. Please advise.', date '2022-02-25')
  into ticket_archive values (6832, 2, 'Billing', 'Sales tax calculated incorrectly', 'The tax on the last invoice is wrong for our state. We are tax exempt and uploaded the certificate. Restarting did not help. Our IT team already checked the network. We are on Atlas Billing 5.1. Please advise.', date '2023-09-28')
