  into ticket_archive values (7791, 4, 'Bug', 'Scheduled report not sent', 'Hello, Subscribers no longer receive the daily KPI report. This started after the last update. We are on Atlas Analytics 6.-1.', date '2022-04-30')
  into ticket_archive values (7792, 4, 'Bug', 'Dashboard numbers do not match invoices', 'Good morning, The revenue dashboard says 48,200 for March but our invoices add up to 51,750. I attached a screenshot. It worked fine last week. Several colleagues have the same problem. We are on Atlas Analytics 6.0. Please advise.', date '2021-08-13')
