  into ticket_archive values (8778, 4, 'Bug', 'Revenue chart shows wrong totals', 'Good morning, Totals in Analytics differ from the Billing module for the same period. Our IT team already checked the network. We are on Atlas Analytics 6.-1. Please advise.', date '2022-02-27')
  into ticket_archive values (8779, 2, 'Billing', 'Downgrade plan at renewal', 'Hi team, We would like to downgrade to Basic when the contract renews next month. Our IT team already checked the network. This started after the last update. We are on Atlas Billing 5.2.', date '2025-07-11')
