insert all
  into ticket_archive values (10101, 1, 'Question', 'Sales forecast setup', 'Hi team, Can Atlas CRM show next quarter''s expected revenue based on deal probability? We are a small team, so this hurts. Restarting did not help. Please advise.', date '2022-04-23')
  into ticket_archive values (10102, 3, 'Bug', 'Edits made without signal disappeared', 'Hi team, Working in airplane mode, my edits did not upload when I landed. Our IT team already checked the network. We need this fixed before the end of the month. I attached a screenshot. Thanks.', date '2022-01-22')
  into ticket_archive values (10103, 1, 'Question', 'How to forecast revenue by quarter', 'Good morning, Is there a report that predicts how much we will close this quarter? We need this fixed before the end of the month. It worked fine last week. Regards.', date '2021-08-20')
  into ticket_archive values (10104, 3, 'Bug', 'Mobile app crashes on startup', 'Good morning, The Android app closes as soon as I open it. I already reinstalled it twice. It only happens some of the time. This started after the last update. We are on Atlas Mobile 3.8. Please advise.', date '2024-01-21')
  into ticket_archive values (10105, 1, 'Bug', 'Pipeline view does not load', 'Hi team, Since the 8.4 update the pipeline page only shows a spinning wheel and never loads. It happens on every computer we tried. Restarting did not help. Regards.', date '2024-06-04')
  into ticket_archive values (10106, 5, 'Bug', 'No webhook calls since yesterday', 'Hello, Our system no longer receives the deal.updated webhook. Nothing changed on our side. It worked fine last week. I attached a screenshot. We are on Atlas Connect 4.-3. Please advise.', date '2025-12-04')
  into ticket_archive values (10107, 5, 'Account', 'Need to enable two-factor authentication', 'Good morning, Our auditor requires two-step verification for every user. How do we enforce it for the whole company? I attached a screenshot. This started after the last update. We are on Atlas Connect 4.0. Thanks.', date '2025-11-18')
  into ticket_archive values (10108, 2, 'Billing', 'Where are old receipts', 'Hi team, I cannot find the receipts for the previous quarter in the billing section. We are on Atlas Billing 5.2. Regards.', date '2023-11-18')
