  into ticket_archive values (11078, 2, 'Billing', 'Wrong tax on invoice', 'Hi, Our invoice includes 20% VAT although we entered our EU VAT number and should be reverse charged. It happens on every computer we tried. We are on Atlas Billing 5.-1. Please advise.', date '2025-02-20')
