  into ticket_archive values (11181, 1, 'Account', 'Login keeps saying invalid credentials', 'Our sales manager is unable to access her account. The error is "invalid credentials" even with the new password from the reset link. This is blocking our work. Thank you for your help.', date '2022-09-01')
