  into ticket_archive values (11545, 2, 'Billing', 'Sales tax calculated incorrectly', 'Hello, The tax on the last invoice is wrong for our state. We are tax exempt and uploaded the certificate. We are on Atlas Billing 5.-1. Thank you for your help.', date '2024-05-22')
