  into ticket_archive values (12312, 2, 'Billing', 'Duplicate charge on credit card', 'Our card statement shows two identical charges for the March subscription. Please refund one of them. It worked fine last week. Our IT team already checked the network. We need this fixed before the end of the month.', date '2022-10-27')
  into ticket_archive values (12313, 4, 'Bug', 'Revenue chart shows wrong totals', 'Totals in Analytics differ from the Billing module for the same period. It worked fine last week. This is blocking our work. Regards.', date '2025-05-13')
