  into ticket_archive values (12860, 1, 'Account', 'Need to enable two-factor authentication', 'Good morning, Our auditor requires two-step verification for every user. How do we enforce it for the whole company? We need this fixed before the end of the month. Our IT team already checked the network. We are on Atlas CRM 8.1. Regards.', date '2024-04-09')
  into ticket_archive values (12861, 5, 'Account', 'Authenticator app codes rejected', 'Hello, Our auditor requires two-step verification for every user. How do we enforce it for the whole company? It worked fine last week. We are a small team, so this hurts. We are on Atlas Connect 4.-2. Thanks.', date '2021-11-16')
