  into ticket_archive values (13595, 4, 'Feature Request', 'Request: dark theme', 'Hi, Our team works late and would love a dark theme in the web application. We are a small team, so this hurts. We need this fixed before the end of the month. Thank you for your help.', date '2021-05-04')
  into ticket_archive values (13596, 3, 'Account', 'Authenticator app codes rejected', 'Hi, The six-digit codes from my authenticator app are always rejected as invalid. This is blocking our work. We are on Atlas Mobile 3.8. Thank you for your help.', date '2025-09-18')
  into ticket_archive values (13597, 1, 'Bug', 'Same customer appears twice', 'Good morning, After uploading our spreadsheet the contact list is full of duplicates. How do we merge them? We are on Atlas CRM 8.3. Thank you for your help.', date '2021-08-27')
