  into ticket_archive values (13605, 2, 'Billing', 'Wrong tax on invoice', 'Good morning, The tax on the last invoice is wrong for our state. We are tax exempt and uploaded the certificate. I attached a screenshot. Please advise.', date '2024-02-20')
  into ticket_archive values (13606, 2, 'Account', 'Login keeps saying invalid credentials', 'Good morning, Since this morning nobody on our team can sign in. The page says the user name or password is wrong, but we reset the password twice. Restarting did not help. We are on Atlas Billing 5.0.', date '2023-10-07')
  into ticket_archive values (13607, 6, 'Bug', 'Sync app shows pending forever', 'Hi, My Mac shows the sync icon spinning all the time but nothing uploads. Our IT team already checked the network. We are a small team, so this hurts.', date '2025-07-11')
