  into ticket_archive values (17566, 1, 'Question', 'Sales forecast setup', 'Hi, How do we set up a weighted forecast for each sales rep? Regards.', date '2024-12-26')
  into ticket_archive values (17567, 6, 'Account', 'Sign-in fails after password change', 'Good morning, After three failed attempts my account got locked and the unlock e-mail never arrived. I need access for a client meeting today. This is blocking our work. We are on Atlas Sync 2.6. Regards.', date '2025-02-24')
