  into ticket_archive values (20907, 6, 'Question', 'Deploy sync client with Intune', 'Hello, How can IT install Atlas Sync without each user clicking through the setup? We need this fixed before the end of the month. Thank you for your help.', date '2024-07-26')
  into ticket_archive values (20908, 2, 'Account', 'Password reset e-mail not received', 'Hi team, I clicked "Forgot password" four times and no e-mail came, not even in spam. We are on Atlas Billing 5.-1. Please advise.', date '2022-02-14')
