  into ticket_archive values (23425, 1, 'Account', 'Need to enable two-factor authentication', 'Hi, The six-digit codes from my authenticator app are always rejected as invalid. We are on Atlas CRM 8.4. Regards.', date '2021-09-05')
  into ticket_archive values (23426, 6, 'Account', 'Cannot log in', 'Good morning, I changed my password yesterday and now Atlas will not let me in. It just returns to the sign-in page without any message. This started after the last update. Several colleagues have the same problem. We are on Atlas Sync 2.4.', date '2025-09-18')
