  into ticket_archive values (23535, 2, 'Billing', 'VAT number not applied', 'The tax on the last invoice is wrong for our state. We are tax exempt and uploaded the certificate. We are on Atlas Billing 5.-1.', date '2023-01-15')
  into ticket_archive values (23536, 4, 'Bug', 'Weekly dashboard e-mail missing', 'Hi, Subscribers no longer receive the daily KPI report. This is blocking our work. Restarting did not help. Thank you for your help.', date '2022-10-19')
  into ticket_archive values (23537, 4, 'Bug', 'Dashboard numbers do not match invoices', 'Hello, The revenue dashboard says 48,200 for March but our invoices add up to 51,750. We are a small team, so this hurts.', date '2023-06-04')
