  into ticket_archive values (23664, 4, 'Feature Request', 'Allow extra fields in billing documents', 'Hi, Our clients require a cost center field on invoices. Please add it. Restarting did not help.', date '2025-08-22')
  into ticket_archive values (23665, 1, 'Account', 'Password reset e-mail not received', 'Hi team, The password reset message does not reach our mailboxes. We use Microsoft 365 with strict filtering. We need this fixed before the end of the month. Thanks.', date '2025-07-29')
  into ticket_archive values (23666, 5, 'Bug', 'Webhooks not firing', 'Hi, We are not getting any events from Atlas Connect anymore, so our ERP is out of date. We are on Atlas Connect 4.-3. Please advise.', date '2025-11-14')
  into ticket_archive values (23667, 6, 'Question', 'Install Atlas Sync for all employees', 'Good morning, How can IT install Atlas Sync without each user clicking through the setup? We are a small team, so this hurts. We are on Atlas Sync 2.6. Regards.', date '2024-05-28')
  into ticket_archive values (23668, 5, 'Question', 'API rate limit exceeded', 'Hello, The REST API started rejecting our calls with a rate limit error. We are on Atlas Connect 4.0.', date '2022-12-01')
  into ticket_archive values (23669, 3, 'Account', 'No reset link in inbox', 'Good morning, Where is the reset link? I requested it an hour ago and still nothing in my inbox. Regards.', date '2025-02-08')
