  into ticket_archive values (26752, 3, 'Question', 'Does offline mode work for billing', 'Hi team, Can our technicians create invoices on the mobile app in places without coverage? We need this fixed before the end of the month. This is blocking our work. Regards.', date '2024-09-20')
  into ticket_archive values (26753, 1, 'Bug', 'Sales pipeline blank after update', 'Hi, The deals board is empty for everyone on the team. Yesterday it showed 120 open deals. We need this fixed before the end of the month. We are on Atlas CRM 8.2. Thanks.', date '2025-06-25')
