  into ticket_archive values (28593, 4, 'Bug', 'Report subscription stopped', 'Good morning, The scheduled export to finance stopped working three weeks ago without any error. We are a small team, so this hurts.', date '2021-12-02')
  into ticket_archive values (28594, 1, 'Account', 'Cannot log in', 'Since this morning nobody on our team can sign in. The page says the user name or password is wrong, but we reset the password twice. We need this fixed before the end of the month. This started after the last update. Several colleagues have the same problem. Thank you for your help.', date '2022-03-31')
