insert all
  into ticket_archive values (29901, 6, 'Question', 'Silent install of desktop app', 'Does the desktop client support deployment with Microsoft Intune or Jamf? This started after the last update. We are on Atlas Sync 2.5.', date '2025-09-04')
  into ticket_archive values (29902, 1, 'Bug', 'Pipeline view does not load', 'Hello, Since the 8.4 update the pipeline page only shows a spinning wheel and never loads. I attached a screenshot. We are on Atlas CRM 8.3.', date '2021-11-07')
