  into ticket_archive values (30113, 5, 'Bug', 'Webhooks not firing', 'Good morning, We are not getting any events from Atlas Connect anymore, so our ERP is out of date. This started after the last update. Thanks.', date '2023-06-15')
  into ticket_archive values (30114, 6, 'Account', 'Sign-in fails after password change', 'Hi team, Since this morning nobody on our team can sign in. The page says the user name or password is wrong, but we reset the password twice. Several colleagues have the same problem. Please call me if you need more details. We are on Atlas Sync 2.4. Thank you for your help.', date '2024-12-09')
