  into ticket_archive values (30550, 1, 'Feature Request', 'Custom fields on invoices', 'Good morning, We need to print the customer''s purchase order number on every invoice. We need this fixed before the end of the month. This started after the last update. Please call me if you need more details. Thank you for your help.', date '2024-08-02')
  into ticket_archive values (30551, 4, 'Bug', 'Weekly dashboard e-mail missing', 'Subscribers no longer receive the daily KPI report. Our IT team already checked the network. Please advise.', date '2022-07-22')
