  into ticket_archive values (32530, 2, 'Billing', 'Need invoice copies for audit', 'Our accountant needs PDF copies of all invoices from last year. Where can I download them? Regards.', date '2021-05-25')
  into ticket_archive values (32531, 2, 'Billing', 'Duplicate charge on credit card', 'We were billed twice for the same invoice. The amount left our bank account on the 3rd and again on the 4th. We are on Atlas Billing 5.-1. Thanks.', date '2021-12-03')
