  into ticket_archive values (32536, 4, 'Account', 'Someone accessed our account', 'Hi, We got an alert about a sign-in from a country where we have no staff. We are on Atlas Analytics 6.-1. Regards.', date '2021-04-27')
  into ticket_archive values (32537, 6, 'Account', 'Unknown sign-in alert', 'Hi team, The security e-mail says a new device logged in to my account at 3 a.m. That was not me. Several colleagues have the same problem. Regards.', date '2024-06-14')
  into ticket_archive values (32538, 2, 'Billing', 'Charged twice this month', 'Hi, There is a double payment for our Professional plan this month. How do we get the money back? It only happens some of the time. This is blocking our work.', date '2023-04-05')
  into ticket_archive values (32539, 6, 'Account', 'How do we turn on 2FA for all users', 'Our auditor requires two-step verification for every user. How do we enforce it for the whole company? Restarting did not help. We are a small team, so this hurts. Please call me if you need more details. We are on Atlas Sync 2.7. Please advise.', date '2023-08-26')
