  into ticket_archive values (33292, 4, 'Bug', 'Weekly dashboard e-mail missing', 'Hi, The scheduled export to finance stopped working three weeks ago without any error. This started after the last update. It only happens some of the time. Thank you for your help.', date '2021-11-23')
  into ticket_archive values (33293, 2, 'Billing', 'Wrong tax on invoice', 'Hello, Why is GST added to our bill? We are registered and the GSTIN is in the account settings. It only happens some of the time. It worked fine last week. We are on Atlas Billing 5.2. Thank you for your help.', date '2025-02-28')
