  into ticket_archive values (33618, 1, 'Bug', 'Sales pipeline blank after update', 'Hi team, The deals board is empty for everyone on the team. Yesterday it showed 120 open deals. We need this fixed before the end of the month. Thank you for your help.', date '2021-12-14')
