  into ticket_archive values (33948, 4, 'Feature Request', 'Add our PO number to invoices', 'Hi, Our clients require a cost center field on invoices. Please add it. Our IT team already checked the network. We are on Atlas Analytics 6.-1. Thanks.', date '2021-05-17')
  into ticket_archive values (33949, 4, 'Bug', 'Report subscription stopped', 'Hi team, Our Monday sales dashboard e-mail did not arrive this week. It happens on every computer we tried. Several colleagues have the same problem. We are a small team, so this hurts. We are on Atlas Analytics 6.-1. Please advise.', date '2022-06-12')
