insert all
  into ticket_archive values (35601, 3, 'Bug', 'Sync overwrote my notes', 'Notes entered offline on the tablet were replaced by the old version from the server. Please call me if you need more details. It happens on every computer we tried. Regards.', date '2023-03-12')
  into ticket_archive values (35602, 6, 'Account', 'Need to enable two-factor authentication', 'Good morning, Can an administrator make multi-factor sign-in mandatory instead of optional? We need this fixed before the end of the month. It worked fine last week. Regards.', date '2025-07-04')
  into ticket_archive values (35603, 3, 'Account', 'Forgot password mail never arrives', 'Hi, The password reset message does not reach our mailboxes. We use Microsoft 365 with strict filtering. This is blocking our work. Restarting did not help. We are on Atlas Mobile 3.7.', date '2022-02-01')
  into ticket_archive values (35604, 3, 'Bug', 'App closes immediately on Android', 'Hi team, Every time I tap the Atlas icon the app opens and shuts down a second later. We are a small team, so this hurts.', date '2025-04-28')
