  into ticket_archive values (37247, 2, 'Billing', 'VAT number not applied', 'Good morning, Why is GST added to our bill? We are registered and the GSTIN is in the account settings. This started after the last update. Thanks.', date '2023-01-16')
  into ticket_archive values (37248, 4, 'Account', 'Cannot log in', 'I changed my password yesterday and now Atlas will not let me in. It just returns to the sign-in page without any message. This started after the last update. Please advise.', date '2023-11-20')
