  into ticket_archive values (37687, 3, 'Bug', 'Sync overwrote my notes', 'Good morning, Notes entered offline on the tablet were replaced by the old version from the server. Several colleagues have the same problem. Regards.', date '2023-01-23')
  into ticket_archive values (37688, 5, 'Question', 'API rate limit exceeded', 'Our nightly sync now fails with "429 Too Many Requests". What is the limit? We are a small team, so this hurts. We are on Atlas Connect 4.-2. Please advise.', date '2024-08-23')
