  into ticket_archive values (38349, 1, 'Feature Request', 'Night mode for the web app', 'Hi team, Our team works late and would love a dark theme in the web application. It happens on every computer we tried. Please call me if you need more details. Please advise.', date '2021-01-21')
  into ticket_archive values (38350, 5, 'Question', 'Sync meetings with Google Calendar', 'Hello, How do I see my Atlas meetings in Outlook? This is blocking our work. Please advise.', date '2023-10-22')
