  into ticket_archive values (38576, 5, 'Question', 'Sync meetings with Google Calendar', 'Hi team, Can we connect the CRM to our Google Workspace calendars? It worked fine last week. Please call me if you need more details. We are on Atlas Connect 4.-2. Thank you for your help.', date '2021-07-05')
  into ticket_archive values (38577, 2, 'Billing', 'Duplicate charge on credit card', 'We were billed twice for the same invoice. The amount left our bank account on the 3rd and again on the 4th. Please call me if you need more details. We are on Atlas Billing 5.-1. Regards.', date '2022-12-26')
