  into ticket_archive values (40096, 1, 'Bug', 'CSV import created duplicates', 'Good morning, We imported 5,000 contacts from a CSV file and now many people appear twice. We are on Atlas CRM 8.4. Regards.', date '2025-10-02')
  into ticket_archive values (40097, 4, 'Account', 'Locked out of my account', 'Good morning, Since this morning nobody on our team can sign in. The page says the user name or password is wrong, but we reset the password twice. We need this fixed before the end of the month. Restarting did not help. We are on Atlas Analytics 6.1.', date '2023-01-15')
