insert all
  into ticket_archive values (41301, 4, 'Question', 'Download dashboard as spreadsheet', 'Good morning, How can I get the numbers behind a chart into Excel? Restarting did not help. We are on Atlas Analytics 6.0.', date '2024-08-18')
  into ticket_archive values (41302, 4, 'Bug', 'Scheduled report not sent', 'Hi, Our Monday sales dashboard e-mail did not arrive this week. Restarting did not help. Several colleagues have the same problem. It worked fine last week. Please advise.', date '2025-05-29')
  into ticket_archive values (41303, 5, 'Question', 'API rate limit exceeded', 'Hi, The REST API started rejecting our calls with a rate limit error. We need this fixed before the end of the month. We are on Atlas Connect 4.-1. Thank you for your help.', date '2021-05-02')
  into ticket_archive values (41304, 3, 'Question', 'Use the app without internet', 'Good morning, Which data is available offline on the phone? It happens on every computer we tried. Several colleagues have the same problem. We are on Atlas Mobile 3.8. Regards.', date '2021-02-07')
  into ticket_archive values (41305, 1, 'Bug', 'Same customer appears twice', 'Hi team, The import ignored existing records and created a second copy of each contact. This started after the last update. Our IT team already checked the network. We need this fixed before the end of the month. Thank you for your help.', date '2021-05-06')
  into ticket_archive values (41306, 4, 'Bug', 'Report subscription stopped', 'Good morning, Subscribers no longer receive the daily KPI report. We need this fixed before the end of the month. Please call me if you need more details. It worked fine last week. We are on Atlas Analytics 6.-1. Please advise.', date '2024-10-13')
  into ticket_archive values (41307, 3, 'Question', 'Download data for offline use', 'Hi, Can our technicians create invoices on the mobile app in places without coverage? This started after the last update. It only happens some of the time. We are on Atlas Mobile 3.7. Thank you for your help.', date '2024-12-10')
  into ticket_archive values (41308, 2, 'Billing', 'Change plan from Professional to Enterprise', 'Good morning, We want to move to the Enterprise plan this week. Will we pay the full price for this month? This is blocking our work. I attached a screenshot. We are a small team, so this hurts. Regards.', date '2022-10-30')
  into ticket_archive values (41309, 3, 'Bug', 'Offline changes lost', 'Hi, Notes entered offline on the tablet were replaced by the old version from the server. We are on Atlas Mobile 3.7. Thanks.', date '2025-04-15')
  into ticket_archive values (41310, 1, 'Bug', 'Pipeline view does not load', 'Hi team, Opening the sales pipeline takes forever and then shows a blank page. Other pages work. Please advise.', date '2022-04-19')
  into ticket_archive values (41311, 5, 'Bug', 'No webhook calls since yesterday', 'Our system no longer receives the deal.updated webhook. Nothing changed on our side. It worked fine last week.', date '2021-11-14')
