  into ticket_archive values (41404, 6, 'Account', 'No reset link in inbox', 'The password reset message does not reach our mailboxes. We use Microsoft 365 with strict filtering. It worked fine last week. Restarting did not help. This is blocking our work. We are on Atlas Sync 2.5. Regards.', date '2024-09-14')
  into ticket_archive values (41405, 2, 'Billing', 'Sales tax calculated incorrectly', 'The tax on the last invoice is wrong for our state. We are tax exempt and uploaded the certificate. Our IT team already checked the network. It happens on every computer we tried. Thank you for your help.', date '2025-03-16')
  into ticket_archive values (41406, 2, 'Billing', 'Where are old receipts', 'Good morning, Our accountant needs PDF copies of all invoices from last year. Where can I download them? Our IT team already checked the network. Thank you for your help.', date '2022-07-06')
  into ticket_archive values (41407, 4, 'Account', 'Change user role to admin', 'I need to give my colleague administrator rights. We are a small team, so this hurts. Thanks.', date '2022-05-21')
