insert all
  into ticket_archive values (45901, 4, 'Bug', 'Analytics totals are off', 'Hi team, The revenue dashboard says 48,200 for March but our invoices add up to 51,750. Restarting did not help. It only happens some of the time. I attached a screenshot. We are on Atlas Analytics 6.-2. Regards.', date '2021-05-23')
  into ticket_archive values (45902, 1, 'Bug', 'Sales pipeline blank after update', 'Hi team, Opening the sales pipeline takes forever and then shows a blank page. Other pages work. Please call me if you need more details. We are on Atlas CRM 8.4. Thank you for your help.', date '2023-10-16')
  into ticket_archive values (45903, 2, 'Feature Request', 'Custom fields on invoices', 'Our clients require a cost center field on invoices. Please add it. It happens on every computer we tried. Our IT team already checked the network. Regards.', date '2021-12-17')
  into ticket_archive values (45904, 5, 'Question', 'API rate limit exceeded', 'Hi, Our nightly sync now fails with "429 Too Many Requests". What is the limit? This is blocking our work. It worked fine last week. We are a small team, so this hurts. We are on Atlas Connect 4.-3. Thanks.', date '2023-01-30')
  into ticket_archive values (45905, 2, 'Billing', 'Where are old receipts', 'Good morning, I cannot find the receipts for the previous quarter in the billing section. Our IT team already checked the network. Please advise.', date '2024-11-19')
  into ticket_archive values (45906, 6, 'Bug', 'Files not syncing on Windows', 'Hi team, Atlas Sync on Windows has said "Syncing 312 items" for two days. We are a small team, so this hurts. Thanks.', date '2024-10-18')
  into ticket_archive values (45907, 5, 'Question', 'Sync meetings with Google Calendar', 'Hi, Meetings booked in Atlas should show up in our calendar app. It happens on every computer we tried. Regards.', date '2022-07-02')
  into ticket_archive values (45908, 5, 'Question', 'Getting HTTP 429 from the API', 'Hi, How many API requests per minute are allowed on the Professional plan? We are on Atlas Connect 4.0. Thanks.', date '2023-04-18')
  into ticket_archive values (45909, 1, 'Bug', 'Same customer appears twice', 'Good morning, The import ignored existing records and created a second copy of each contact. Our IT team already checked the network. We are on Atlas CRM 8.1. Regards.', date '2022-11-26')
  into ticket_archive values (45910, 3, 'Bug', 'Edits made without signal disappeared', 'Hi, I updated ten customer visits while I had no signal, and after reconnecting all my changes were gone. We are a small team, so this hurts. It happens on every computer we tried. We are on Atlas Mobile 3.7. Thanks.', date '2025-10-13')
