  into ticket_archive values (45920, 2, 'Billing', 'Upgrade subscription mid-cycle', 'How do I upgrade our subscription? Is the price prorated? It worked fine last week. We are on Atlas Billing 5.0. Regards.', date '2022-06-27')
  into ticket_archive values (45921, 3, 'Account', 'Change user role to admin', 'I need to give my colleague administrator rights. It worked fine last week. We are on Atlas Mobile 3.9. Thanks.', date '2024-12-31')
