  into ticket_archive values (48420, 5, 'Question', 'API rate limit exceeded', 'Hi, How many API requests per minute are allowed on the Professional plan? Our IT team already checked the network. We are on Atlas Connect 4.0. Please advise.', date '2025-09-09')
