  into ticket_archive values (49750, 6, 'Account', 'Authenticator app codes rejected', 'Good morning, The six-digit codes from my authenticator app are always rejected as invalid. We are a small team, so this hurts. This started after the last update. Restarting did not help.', date '2024-02-22')
  into ticket_archive values (49751, 5, 'Feature Request', 'Night mode for the web app', 'Hi team, Please consider a night theme like the mobile app has. It only happens some of the time. We are a small team, so this hurts. Our IT team already checked the network.', date '2022-06-17')
